CREATE OR REPLACE FUNCTION public.get_user_my_tasks(p_emp_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$ DECLARE   v_today          DATE := CURRENT_DATE;   v_emp_email      TEXT;   v_is_admin       BOOLEAN := false;   v_tasks          jsonb;   v_employees      jsonb; BEGIN   SELECT email INTO v_emp_email FROM employee_master WHERE emp_id = p_emp_id;   IF v_emp_email = 'vsv.vempati@gmail.com' THEN     v_is_admin := true;   END IF;    DROP TABLE IF EXISTS temp_my_tasks_raw;   CREATE TEMPORARY TABLE temp_my_tasks_raw ON COMMIT DROP AS   (     SELECT       t.task_id,       t.task_cd,       t.task_nm,       t.task_desc,       t.task_asgn_to,       t.emp_id,       t.ext_emp_id,       t.task_dep_flg,       t.task_dep_typ,       t.dep_task_id,       t.no_of_days,       t.wrk_days,       t.chk_flg,       t.atta_flg,       t.atta_file_id,       t.note_txt,       t.st_dt,       t.end_dt,       t.act_cmp_dt,       t.prcs_flg,       t.prcs_yes_actn,       tsm.status_nm AS task_sts,       pm.priority_nm AS priority,       t.addl_rem,       t.m_id,       false AS is_individual,       COALESCE(         (SELECT pc.emp_id FROM process_config pc WHERE pc.task_id = t.task_id AND pc.is_live = true AND pc.ordr_id = 1 LIMIT 1),         NULL       ) AS reviewer_id,       COALESCE(         (SELECT pc.emp_id FROM process_config pc WHERE pc.task_id = t.task_id AND pc.is_live = true AND pc.ordr_id = 2 LIMIT 1),         NULL       ) AS approver_id,       COALESCE(         (SELECT COUNT(*) FROM checklist_master chk WHERE chk.task_id = t.task_id AND chk.is_live = true AND chk.sts = true),         0       ) AS chk_total,       COALESCE(         (SELECT COUNT(*) FROM checklist_master chk WHERE chk.task_id = t.task_id AND chk.is_live = true AND chk.sts = true AND chk.chk_sts = true),         0       ) AS chk_completed     FROM task_live_master t     LEFT JOIN task_status_master tsm ON tsm.status_id = t.task_sts     LEFT JOIN task_priority_master pm ON pm.priority_id = t.priority      UNION ALL      SELECT       t.emp_task_id AS task_id,       t.task_cd,       t.task_nm,       t.task_desc,       t.task_asgn_to,       t.emp_id,       NULL AS ext_emp_id,       NULL AS task_dep_flg,       NULL AS task_dep_typ,       NULL AS dep_task_id,       NULL AS no_of_days,       NULL AS wrk_days,       t.chk_flg,       t.atta_flg,       NULL AS atta_file_id,       NULL AS note_txt,       t.st_dt,       t.end_dt,       CASE WHEN tsm.status_nm = 'COMPLETED' THEN t.end_dt ELSE NULL END AS act_cmp_dt,       t.prcs_flg,       t.prcs_yes_actn,       tsm.status_nm AS task_sts,       pm.priority_nm AS priority,       t.remarks AS addl_rem,       NULL AS m_id,       true AS is_individual,       COALESCE(         (SELECT pc.emp_id FROM process_config pc WHERE pc.emp_task_id = t.emp_task_id AND pc.ordr_id = 1 LIMIT 1),         NULL       ) AS reviewer_id,       COALESCE(         (SELECT pc.emp_id FROM process_config pc WHERE pc.emp_task_id = t.emp_task_id AND pc.ordr_id = 2 LIMIT 1),         NULL       ) AS approver_id,       COALESCE(         (SELECT COUNT(*) FROM checklist_master chk WHERE chk.emp_task_id = t.emp_task_id AND chk.sts = true),         0       ) AS chk_total,       COALESCE(         (SELECT COUNT(*) FROM checklist_master chk WHERE chk.emp_task_id = t.emp_task_id AND chk.sts = true AND chk.chk_sts = true),         0       ) AS chk_completed     FROM employee_individual_task_master t     LEFT JOIN task_status_master tsm ON tsm.status_id = t.task_sts     LEFT JOIN task_priority_master pm ON pm.priority_id = t.priority     WHERE COALESCE(t.sts, true) = true   );    SELECT jsonb_agg(sub) INTO v_tasks   FROM (     SELECT       t.task_id AS "taskId",       t.task_cd AS "taskCd",       t.task_nm AS "taskNm",       t.task_desc AS "taskDesc",       t.task_asgn_to AS "taskAsgnTo",       t.emp_id AS "empId",       t.ext_emp_id AS "extEmpId",       t.task_dep_flg AS "taskDepFlg",       t.task_dep_typ AS "taskDepTyp",       t.dep_task_id AS "depTaskId",       t.no_of_days AS "noOfDays",       t.wrk_days AS "wrkDays",       t.chk_flg AS "chkFlg",       t.atta_flg AS "attaFlg",       t.atta_file_id AS "attaFileId",       t.note_txt AS "noteTxt",       t.st_dt AS "stDt",       t.end_dt AS "endDt",       t.act_cmp_dt AS "actCmpDt",       t.prcs_flg AS "prcsFlg",       t.prcs_yes_actn AS "prcsYesActn",       t.task_sts AS "taskSts",       t.priority AS "priority",       t.addl_rem AS "addlRem",       t.m_id AS "mId",       t.is_individual AS "isIndividual",       t.reviewer_id AS "reviewerId",       t.approver_id AS "approverId",       CASE         WHEN t.task_sts = 'COMPLETED' THEN 100         WHEN t.prcs_flg = true AND t.task_sts = 'UNDER_REVIEW' THEN 95         WHEN t.prcs_flg = true AND t.task_sts = 'SUBMIT_REVIEW' THEN 90         WHEN t.chk_total > 0 THEN ROUND((t.chk_completed::NUMERIC / t.chk_total) * 100)::INT         ELSE 0       END AS "progress",       CASE         WHEN t.is_individual THEN 'Individual Task'         ELSE COALESCE(p.prj_nm, 'Unknown Project')       END AS "projectName",       CASE         WHEN t.is_individual THEN 'Internal'         ELSE COALESCE(p.prj_cd, '')       END AS "projectCode",       CASE         WHEN t.is_individual THEN '-'         ELSE COALESCE(m.mlstn_ttl, 'Unknown Milestone')       END AS "milestoneTitle"     FROM temp_my_tasks_raw t     LEFT JOIN milestone_live_master m ON m.m_id = t.m_id     LEFT JOIN project_live_master p ON p.prj_id = m.prj_id     WHERE v_is_admin = true        OR t.emp_id = p_emp_id        OR t.reviewer_id = p_emp_id        OR t.approver_id = p_emp_id   ) sub;    SELECT jsonb_agg(sub_emp) INTO v_employees   FROM (     SELECT       emp_id AS "empId",       email AS "email",       TRIM(COALESCE(fst_nm,'')||' '||COALESCE(lst_nm,'')) AS "employeeName",       photo_url AS "photoUrl"     FROM employee_master     WHERE sts = true   ) sub_emp;    RETURN jsonb_build_object(     'tasks', COALESCE(v_tasks, '[]'::jsonb),     'employees', COALESCE(v_employees, '[]'::jsonb)   ); END; $function$
